                json!([{"field": "region", "values": ["\"North\"", "\"South\""]}]);
            payload_json["rows"] = json!(xs
                .iter()
                .flat_map(|(x, y)| vec![
                    json!({"product": x, "region": "North", "revenue": y, "target": 50.0}),
                    json!({"product": x, "region": "South", "revenue": y, "target": 50.0}),
                ])
                .collect::<Vec<_>>());
